#!/usr/bin/env python3
"""Write common/recoil/names.lua: what each Lua handle registers, read off the pinned recoil-lua-library.

The library's handles/ (RecoilEngine#2799) types the engine once per handle: Recoil.Shared is what both handles
offer, Recoil.Synced and Recoil.Unsynced extend it with what one registers alone. emmylua_doc_cli reads those
classes as JSON, and this reads the JSON:

    recoil_names.py [emmylua_doc_cli]        # from the repo root; the tool on PATH when not given

The Spring members per handle are the members of its class. The top-level globals per handle are the globals its
generated file defines; the library's hand-written files (Script, tracy) are both handles'. A name both handle
classes carry (the engine documents its own copy of GiveOrder* in each) is shared, not either handle's alone.

The engine documents the standard library each handle keeps as globals too (pairs, io, debug...). Lua 5.1's
standard library is a fixed list, so a global on it goes to the `*Language` lists and any other to `*Globals`.
"""

import json
import os
import subprocess
import sys
import tempfile

LIBRARY = "recoil-lua-library"
OUT = "common/recoil/names.lua"

HANDLE_FILES = {
    "shared": "handles/generated/shared.lua",
    "synced": "handles/generated/synced.lua",
    "unsynced": "handles/generated/unsynced.lua",
}

# Lua 5.1's standard library: base, and the libraries it opens. Fixed by the language, so kept here.
LUA_51 = {
    "_G", "_VERSION", "assert", "collectgarbage", "dofile", "error", "gcinfo", "getfenv", "getmetatable", "ipairs",
    "load", "loadfile", "loadstring", "module", "newproxy", "next", "pairs", "pcall", "print", "rawequal", "rawget",
    "rawset", "require", "select", "setfenv", "setmetatable", "tonumber", "tostring", "type", "unpack", "xpcall",
    "coroutine", "debug", "io", "math", "os", "package", "string", "table",
}

# What a handle's class adds to Spring, by the class's name.
HANDLE_CLASSES = {
    "shared": "Recoil.Shared",
    "synced": "Recoil.Synced",
    "unsynced": "Recoil.Unsynced",
}

HEADER = """\
-- GENERATED by .github/scripts/recoil_names.py from recoil-lua-library/handles; do not edit. CI writes it again
-- whenever the submodule pin moves, and fails a pull request whose copy differs from the pin's.
-- The Spring members (functions, sub-tables, constants) and the top-level globals per Lua handle: `shared*` what
-- both handles have, `syncedOnly*` and `unsyncedOnly*` what one has alone; `*Language` is the standard library.
"""


def handle_of(path):
    """The handle whose generated file this is, "shared" for the library's hand-written files, or None."""
    path = path.replace("\\", "/")
    for handle, suffix in HANDLE_FILES.items():
        if path.endswith("/" + suffix):
            return handle
    if "/library/" in path and "/library/generated/" not in path and not path.endswith("/library/Spring.lua"):
        return "shared"
    return None


def read(doc):
    types = {t["name"]: t for t in doc["types"]}
    members = {}
    for handle, name in HANDLE_CLASSES.items():
        if name not in types:
            sys.exit(f"recoil_names: no class {name} in the library: is recoil-lua-library/handles there?")
        members[handle] = {m["name"] for m in types[name].get("members") or []}

    globals_ = {"shared": set(), "synced": set(), "unsynced": set()}
    for g in doc["globals"]:
        if g["name"] == "Spring":
            continue
        handle = handle_of((g.get("loc") or {}).get("file") or "")
        if handle is not None:
            globals_[handle].add(g["name"])
    return members, globals_


def split(by_handle):
    both = by_handle["shared"] | (by_handle["synced"] & by_handle["unsynced"])
    return both, by_handle["synced"] - both, by_handle["unsynced"] - both


def lua_list(key, names):
    if not names:
        return [f"\t{key} = {{}},"]
    lines = [f"\t{key} = {{"]
    lines += [f'\t\t"{name}",' for name in sorted(names)]
    lines.append("\t},")
    return lines


def document(doc_cli):
    """The library as emmylua_doc_cli's JSON: the handle classes, and the hand-written files' globals."""
    with tempfile.TemporaryDirectory() as tmp:
        out = os.path.join(tmp, "doc.json")
        subprocess.run(
            [
                doc_cli,
                f"{LIBRARY}/handles",
                f"{LIBRARY}/library",
                "--exclude",
                "**/library/generated/**,**/library/Spring.lua",
                "--output-format",
                "json",
                "--output",
                out,
            ],
            check=True,
            stdout=subprocess.DEVNULL,
        )
        with open(out, encoding="utf-8") as f:
            return json.load(f)


def main():
    if len(sys.argv) > 2:
        sys.exit("usage: recoil_names.py [emmylua_doc_cli]")
    members, globals_ = read(document(sys.argv[1] if len(sys.argv) == 2 else "emmylua_doc_cli"))
    shared, synced_only, unsynced_only = split(members)
    language = {handle: names & LUA_51 for handle, names in globals_.items()}
    engine = {handle: names - LUA_51 for handle, names in globals_.items()}
    shared_globals, synced_only_globals, unsynced_only_globals = split(engine)
    shared_language, synced_only_language, unsynced_only_language = split(language)

    lines = [HEADER.rstrip("\n"), "return {"]
    lines += lua_list("shared", shared)
    lines += lua_list("sharedGlobals", shared_globals)
    lines += lua_list("syncedOnly", synced_only)
    lines += lua_list("unsyncedOnly", unsynced_only)
    lines += lua_list("syncedOnlyGlobals", synced_only_globals)
    lines += lua_list("unsyncedOnlyGlobals", unsynced_only_globals)
    lines += lua_list("sharedLanguage", shared_language)
    lines += lua_list("syncedOnlyLanguage", synced_only_language)
    lines += lua_list("unsyncedOnlyLanguage", unsynced_only_language)
    lines.append("}")
    # CRLF, as .gitattributes checks out every .lua and stylua.toml formats it
    with open(OUT, "w", encoding="utf-8", newline="\r\n") as f:
        f.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
